from collections import deque

def quickestWayUp(ladders, snakes):
    # Create a graph where each node represents a square on the board
    # and edges represent the possible moves (rolls of the die)
    graph = {i: [] for i in range(1, 101)}

    # Add edges for ladders
    for start, end in ladders:
        graph[start] = [end]

    # Add edges for snakes
    for start, end in snakes:
        graph[start] = [end]

    # Add edges for all possible rolls of the die
    for i in range(1, 101):
        for roll in range(1, 7):
            if i + roll <= 100:
                graph[i].append(i + roll)

    # Perform a breadth-first search to find the shortest path to 100
    queue = deque([(1, 0)])  # (current_square, number_of_rolls)
    visited = set([1])

    while queue:
        current_square, number_of_rolls = queue.popleft()

        if current_square == 100:
            return number_of_rolls

        for neighbor in graph[current_square]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, number_of_rolls + 1))

    return -1

